<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class CustomerSupportService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access,private readonly SupportDiagnosticsService $diagnostics) {}
    private function ownSite(mixed $id):array {$site=$this->access->requireSite($id);$user=$this->row('users','user_id',$this->actor());$p=['company'=>$this->company(),'site'=>$site['site_id'],'actor'=>$this->actor()];$grant=$this->db->fetch('SELECT grant_id FROM user_site_grants WHERE company_id=:company AND site_id=:site AND user_id=:actor',$p);$client=$this->db->fetch('SELECT client_id FROM client_portal_access WHERE company_id=:company AND user_id=:actor AND client_id=:client',['company'=>$this->company(),'actor'=>$this->actor(),'client'=>$site['client_id']]);$shift=$this->db->fetch("SELECT shift_assignment_id FROM shift_assignments WHERE company_id=:company AND site_id=:site AND employee_id=:employee AND deleted_at IS NULL AND assignment_status IN ('ASSIGNED','CONFIRMED','IN_PROGRESS') AND shift_end_at>=:now AND shift_start_at<=:until",['company'=>$this->company(),'site'=>$site['site_id'],'employee'=>$user['employee_id']??null,'now'=>gmdate('Y-m-d H:i:s'),'until'=>gmdate('Y-m-d H:i:s',time()+7*86400)]);if(!$grant&&!$client&&!$shift)throw HttpException::notFound('No assigned client/site access for this support request.');return $site;}
    private function ticket(string $id,bool $self):array {$r=$this->row('customer_support_tickets','ticket_id',$id);$site=$this->access->requireSite($r['site_id']);if((string)$site['client_id']!==(string)$r['client_id'])throw HttpException::notFound();if($self&&(string)$r['created_by_user_id']!==$this->actor())throw HttpException::notFound();return $r;}
    public function list(array $input,bool $self=false):array {$this->fields($input,$self?[]:['site_id']);if(!$self)$site=$this->access->requireSite($input['site_id']??null);$rows=$this->db->fetchAll('SELECT * FROM customer_support_tickets WHERE company_id=:company'.($self?' AND created_by_user_id=:actor':' AND site_id=:site AND client_id=:client').' ORDER BY ticket_id DESC LIMIT 200',$self?['company'=>$this->company(),'actor'=>$this->actor()]:['company'=>$this->company(),'site'=>$site['site_id'],'client'=>$site['client_id']]);$out=[];foreach($rows as$r){if(!$this->access->allowed($r['site_id']))continue;$current=$this->site($r['site_id']);if((string)$current['client_id']!==(string)$r['client_id'])continue;$r['messages']=$this->db->fetchAll('SELECT actor_user_id,message,created_at FROM customer_support_messages WHERE company_id=:company AND ticket_id=:ticket ORDER BY message_id',['company'=>$this->company(),'ticket'=>$r['ticket_id']]);$r['diagnostics']=$this->db->fetchAll('SELECT consent_id,shared_at,revoked_at,snapshot_hash FROM support_diagnostic_consents WHERE company_id=:company AND ticket_id=:ticket ORDER BY consent_id',['company'=>$this->company(),'ticket'=>$r['ticket_id']]);$out[]=$r;}return $out;}
    public function create(array $input,bool $self=false):array {return $this->atomic(function()use($input,$self){$this->fields($input,['site_id','subject','description','priority']);$site=$self?$this->ownSite($input['site_id']??null):$this->access->requireSite($input['site_id']??null);if(!in_array($input['priority']??null,['NORMAL','HIGH'],true))throw HttpException::unprocessable('Choose NORMAL or HIGH.');$this->db->execute('INSERT INTO customer_support_tickets(company_id,site_id,client_id,created_by_user_id,subject,description,priority,created_at) VALUES(:company,:site,:client,:actor,:subject,:description,:priority,:now)',['company'=>$this->company(),'site'=>$site['site_id'],'client'=>$site['client_id'],'actor'=>$this->actor(),'subject'=>$this->text($input['subject']??null,150),'description'=>$this->text($input['description']??null,6000),'priority'=>$input['priority'],'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('customer_support_ticket');});}
    public function action(string $id,string $action,array $input,bool $self=false):array {return $this->atomic(function()use($id,$action,$input,$self){$this->fields($input,$self?['expected_revision','message']:['expected_revision','message','assignee_user_id']);$r=$this->ticket($id,$self);if($this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Ticket changed. Refresh before updating.');$state=$r['state'];$assignee=$r['assignee_user_id'];if($action==='reply'&&$state!=='CLOSED'){}elseif($action==='resolve'&&!$self&&in_array($state,['OPEN','IN_PROGRESS'],true))$state='RESOLVED';elseif($action==='confirm'&&$self&&$state==='RESOLVED')$state='CLOSED';elseif($action==='reopen'&&$self&&$state==='RESOLVED')$state='OPEN';elseif($action==='assign'&&!$self&&in_array($state,['OPEN','IN_PROGRESS'],true)){$user=$this->row('users','user_id',$input['assignee_user_id']??null);if($user['status']!=='ACTIVE')throw HttpException::unprocessable('Choose an active assignee.');$assignee=$user['user_id'];$state='IN_PROGRESS';}else throw HttpException::conflict('This ticket action is not available.');$this->db->execute('UPDATE customer_support_tickets SET state=:state,revision=revision+1,assignee_user_id=:assignee,resolved_at=:resolved WHERE company_id=:company AND ticket_id=:id',['state'=>$state,'assignee'=>$assignee,'resolved'=>in_array($state,['RESOLVED','CLOSED'],true)?($r['resolved_at']??gmdate('Y-m-d H:i:s')):null,'company'=>$this->company(),'id'=>$id]);$this->db->execute('INSERT INTO customer_support_messages(company_id,ticket_id,actor_user_id,message,created_at) VALUES(:company,:ticket,:actor,:message,:now)',['company'=>$this->company(),'ticket'=>$id,'actor'=>$this->actor(),'message'=>$this->text($input['message']??null,3000),'now'=>gmdate('Y-m-d H:i:s')]);$this->audit->record('customer_support_ticket',$action,$id);return ['state'=>$state];});}
    public function share(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['consent']);$this->ticket($id,true);if(($input['consent']??null)!==true)throw HttpException::unprocessable('Explicit consent is required to attach sanitised diagnostics.');$snapshot=$this->diagnostics->report();$snapshot['shared_by_user_id']=$this->actor();$json=json_encode($snapshot,JSON_THROW_ON_ERROR);$this->db->execute('INSERT INTO support_diagnostic_consents(company_id,ticket_id,shared_by_user_id,snapshot_json,snapshot_hash,shared_at) VALUES(:company,:ticket,:actor,:snapshot,:hash,:now)',['company'=>$this->company(),'ticket'=>$id,'actor'=>$this->actor(),'snapshot'=>$json,'hash'=>hash('sha256',$json),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('support_diagnostic_consent');});}
    public function diagnostic(string $id,bool $self=false):array {$r=$this->row('support_diagnostic_consents','consent_id',$id);$this->ticket((string)$r['ticket_id'],$self);if($r['revoked_at']!==null||$r['snapshot_json']===null)throw HttpException::notFound('Diagnostic consent was revoked.');if(!hash_equals($r['snapshot_hash'],hash('sha256',$r['snapshot_json'])))throw HttpException::conflict('Diagnostic snapshot failed integrity verification.');$this->audit->record('support_diagnostic_consent','viewed',$id);return json_decode($r['snapshot_json'],true,512,JSON_THROW_ON_ERROR);}
    public function revoke(string $id):array {return $this->atomic(function()use($id){$r=$this->row('support_diagnostic_consents','consent_id',$id);$this->ticket((string)$r['ticket_id'],true);if((string)$r['shared_by_user_id']!==$this->actor())throw HttpException::notFound();$this->db->execute('UPDATE support_diagnostic_consents SET snapshot_json=NULL,revoked_at=:now WHERE company_id=:company AND consent_id=:id',['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('support_diagnostic_consent','revoked',$id);return ['revoked'=>true];});}
    public function notice(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['title','body','audience']);$audience=$input['audience']??null;if(!in_array($audience,['ALL','STAFF','CLIENT'],true))throw HttpException::unprocessable('Choose ALL, STAFF or CLIENT.');$title=$this->text($input['title']??null,150);$body=$this->text($input['body']??null,10000);$this->db->execute('INSERT INTO release_notices(company_id,title,body,audience,content_hash,published_at,published_by_user_id) VALUES(:company,:title,:body,:audience,:hash,:now,:actor)',['company'=>$this->company(),'title'=>$title,'body'=>$body,'audience'=>$audience,'hash'=>hash('sha256',$title.'|'.$body),'now'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor()]);return $this->created('release_notice');});}
    public function notices():array {$user=$this->row('users','user_id',$this->actor());$client=(bool)$this->db->fetch('SELECT client_id FROM client_portal_access WHERE company_id=:company AND user_id=:actor',['company'=>$this->company(),'actor'=>$this->actor()]);$staff=(new \Sentinel\Repositories\PermissionRepository($this->db,$this->context))->userHasPermission($this->actor(),'guard.self')||(new \Sentinel\Repositories\PermissionRepository($this->db,$this->context))->userHasPermission($this->actor(),'customer_support.view');$rows=$this->db->fetchAll('SELECT notice_id,title,body,audience,content_hash,published_at FROM release_notices WHERE company_id=:company ORDER BY notice_id DESC LIMIT 100',['company'=>$this->company()]);$out=[];foreach($rows as$r){if($r['audience']!=='ALL'&&!(($r['audience']==='STAFF'&&$staff)||($r['audience']==='CLIENT'&&$client)))continue;$r['read_at']=$this->db->fetch('SELECT read_at FROM release_notice_reads WHERE company_id=:company AND notice_id=:notice AND user_id=:actor',['company'=>$this->company(),'notice'=>$r['notice_id'],'actor'=>$this->actor()])['read_at']??null;$out[]=$r;}return $out;}
    public function readNotice(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_hash']);$notice=null;foreach($this->notices()as$n)if((string)$n['notice_id']===$id)$notice=$n;if(!$notice)throw HttpException::notFound();if(!is_string($input['expected_hash']??null)||!hash_equals($notice['content_hash'],$input['expected_hash']))throw HttpException::conflict('Read the current notice first.');if($notice['read_at']===null)$this->db->execute('INSERT INTO release_notice_reads(company_id,notice_id,user_id,content_hash,read_at) VALUES(:company,:notice,:actor,:hash,:now)',['company'=>$this->company(),'notice'=>$id,'actor'=>$this->actor(),'hash'=>$notice['content_hash'],'now'=>gmdate('Y-m-d H:i:s')]);return ['acknowledged'=>true];});}
}
